import { ToggleGroup } from 'moru-ui'
export function ReportingPeriod() {
  return (
    <ToggleGroup
      layout="segmented"
      aria-label="Reporting period"
      preventEmpty
      defaultValue={['week']}
      items={[
        { value: 'week', label: 'Weekly' },
        { value: 'month', label: 'Monthly' },
      ]}
    />
  )
}
